#!/bin/bash
# batch D1: generated by scripts/make_batch.py from tracks/kb/claims_tracks/decisions/D1.tsv; do not edit by hand
cd /data/haiyangw/nrpic/wt/kb || exit 2
fail=0
test -n "${NRPIC_RUN_DIR:-}" || { echo 'not inside nrpic-run'; exit 2; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py snapshot tracks/kb/claims_tracks/decisions/D1.tsv > "$NRPIC_RUN_DIR/before.json" || fail=1
/usr/bin/python3 -I kb/bin/kb claim verify 682 --by kb-claims_tracks --evidence '1305.2619v1 L443 (read): the Gondolo-Silk distribution is a factor of three smaller at its peak than the relativistic one, and with 8Gm replaced by 4Gm it peaks about 15 per cent above the numerical result. D'"'"'s 2.59 and 9.2 per cent are computed values in run D-bh-dress-20261115-145636-5259f48 (reference.json constf/ratio_peak_rel_over_gs8 = 2.5897, excess_peak_gs4_over_rel = 0.0922; file and values checked), not read from Fig. 1 as the claim text says.' || { echo FAILED 682; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 683 --by kb-claims_tracks --evidence '1707.06302v2 L929-931 (read): peak for a = 0.8 about 35 per cent above a = 0.5 (Hernquist), about 20 per cent for the constant distribution. D'"'"'s +45 and +14 per cent are read off the paper'"'"'s figures by D'"'"'s digitizer in run D-bh-dress-20261115-171615-8adbbdd (kerr_curves.json, file present; ratios 1.451 and 1.0585/0.9256 not recomputed here).' || { echo FAILED 683; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 380 --by kb-claims_tracks --evidence '1305.2619v1 L439-441: the Gondolo-Silk profile as written by SFW, rho = (4 pi f0/3)(2Gm/r)^(3/2)(1 - 8Gm/r)^(3/2). The original astro-ph/9906391 is now in the store (v1) and was not compared here.' || { echo FAILED 380; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 408 --by kb-claims_tracks --evidence '2306.11588v2 L86: JWST AGN tests (Lei et al.) favour k ~ -1. The three named papers 2302.13333, 2304.01059, 2305.03408 are not in the store (checked 2026-11-20), so '"'"'not read'"'"' still holds.' || { echo FAILED 408; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 417 --by kb-claims_tracks --evidence '2608.13206v3 L457-486: Zel'"'"'dovich-Novikov accretion law dM/dt = 4 pi F R^2 rho_b, fitted with the Psi <= 0.1 criterion (Table, mu = 0.805-0.9), for a radiation-era fluid.' || { echo FAILED 417; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 418 --by kb-claims_tracks --evidence '2109.04896v3 L89: matter era modelled by an oscillating massive scalar field, perturbation by a massless scalar.' || { echo FAILED 418; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 419 --by kb-claims_tracks --evidence '1805.09034v3: GADGET-2 N-body runs (macro L13, L21; method L61), binaries initialised as point masses plus halos (L290); the r^(-3/2) halo is not a Newtonian isolated equilibrium, so a stand-in is used (L568).' || { echo FAILED 419; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 420 --by kb-claims_tracks --evidence '2302.07878v1 L132 (figure caption): k = 0 is expected for ordinary black holes such as Kerr, k = 3 for vacuum-energy interiors.' || { echo FAILED 420; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 370 --by kb-claims_tracks --evidence '1805.09034v3 L195-199 cites Bertschinger 1985 for rho ~ r^(-3/2); 1901.08528v2 L235 cites Fillmore-Goldreich 1984 and Bertschinger 1985 for r^(-9/4). Both originals (ApJ 281, 1; ApJS 58, 39) predate arXiv and are not in the store.' --locator '1805.09034v3:main.tex:L195-199; 1901.08528v2:PBH-UCMH-ArXiv-v2.tex:L235' || { echo FAILED 370; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim relocate 399 --by kb-claims_tracks --locator 2308.07374v2:BH-in-FLRW-for-arXiv-V2-2023-08-21.tex:L322-326 --evidence '[evidence] The stored locator L6 is a \usepackage line; the derivation starts from the McVittie form at L322-326. Checked [my derivation]: radial null rays dR/dt = sqrt(f)(H R +- sqrt(f)), f = 1 - 2m/R; the minus family stalls at f = H^2 R^2; R_AH = 2m(1 + 4 m^2 H^2 + ...); in Einstein-de Sitter d ln M_AH / d ln a = -12 (m H)^2.' || { echo FAILED 399; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/annotate.py refresh 697 698 699 700 || { echo FAILED refresh; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/annotate.py annotate tracks/kb/claims_tracks/decisions/D1_annot.tsv || { echo FAILED annotate; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim check --id 682 683 380 408 417 418 419 420 --by kb-claims_tracks || { echo FAILED check; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py rows tracks/kb/claims_tracks/decisions/D1.tsv "$NRPIC_RUN_DIR/before.json" "$NRPIC_RUN_ID" > "$NRPIC_RUN_DIR/ledger_rows.tsv" || fail=1
exit $fail
